// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RFQ) predicate.RFQ {
	return predicate.RFQ(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RFQ) predicate.RFQ {
	return predicate.RFQ(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RFQ) predicate.RFQ {
	return predicate.RFQ(sql.NotPredicates(p))
}
